-- ALTER VIEW, ALTER MATERIALIZED VIEW and ALTER TABLE accept every ALTER
-- TABLE subcommand and reject, before running any, those PostgreSQL does not
-- perform on the relation's kind.
CREATE TABLE t197(a int, b int);
CREATE VIEW v197 AS SELECT * FROM t197;
CREATE MATERIALIZED VIEW m197 AS SELECT * FROM t197;
CREATE INDEX i197 ON t197(a);
ALTER VIEW v197 ENABLE TRIGGER tr;
ALTER VIEW v197 DISABLE TRIGGER ALL;
ALTER VIEW v197 ADD COLUMN c int;
ALTER VIEW v197 DROP COLUMN a;
ALTER VIEW v197 ALTER COLUMN a TYPE text;
ALTER VIEW v197 ALTER COLUMN a SET NOT NULL;
ALTER VIEW v197 SET TABLESPACE pg_default;
ALTER VIEW v197 INHERIT t197;
ALTER VIEW v197 ADD CONSTRAINT c CHECK (a > 0);
ALTER VIEW v197 CLUSTER ON i197;
ALTER VIEW v197 SET LOGGED;
ALTER VIEW v197 REPLICA IDENTITY FULL;
ALTER VIEW v197 ENABLE ROW LEVEL SECURITY;
ALTER VIEW v197 ALTER COLUMN a SET STATISTICS 10;
ALTER VIEW v197 ALTER COLUMN a SET DEFAULT 1, ALTER COLUMN b DROP DEFAULT;
ALTER VIEW v197 ALTER COLUMN a SET DEFAULT 1, ADD COLUMN q int;
ALTER VIEW v197 ALTER COLUMN zz SET DEFAULT 1;
ALTER VIEW v197 ALTER COLUMN a ADD GENERATED ALWAYS AS IDENTITY;
ALTER VIEW v197 ALTER COLUMN a DROP IDENTITY;
ALTER VIEW v197 ALTER COLUMN a DROP IDENTITY IF EXISTS;
ALTER VIEW v197 SET (fillfactor = 50);
ALTER VIEW v197 RESET (fillfactor);
ALTER VIEW IF EXISTS nosuch197 ENABLE TRIGGER x;
ALTER VIEW IF EXISTS nosuch197 RENAME TO x;
ALTER VIEW t197 ENABLE TRIGGER x;
ALTER MATERIALIZED VIEW v197 ENABLE TRIGGER x;
ALTER MATERIALIZED VIEW m197 ENABLE TRIGGER tr;
ALTER MATERIALIZED VIEW m197 ADD COLUMN c int;
ALTER MATERIALIZED VIEW m197 ALTER COLUMN a SET DEFAULT 1;
ALTER MATERIALIZED VIEW m197 ALTER COLUMN a DROP DEFAULT;
ALTER MATERIALIZED VIEW m197 ALTER COLUMN a TYPE text;
ALTER MATERIALIZED VIEW m197 SET LOGGED;
ALTER MATERIALIZED VIEW m197 DROP COLUMN a;
ALTER MATERIALIZED VIEW m197 CLUSTER ON i197;
ALTER MATERIALIZED VIEW m197 CLUSTER ON nosuch197;
ALTER MATERIALIZED VIEW m197 ALTER COLUMN a SET STATISTICS 10;
ALTER MATERIALIZED VIEW IF EXISTS nosuch197 SET (fillfactor = 50);
ALTER TABLE v197 ENABLE TRIGGER tr;
ALTER TABLE v197 ALTER COLUMN a SET DEFAULT 3;
ALTER TABLE v197 ADD COLUMN c int;
ALTER TABLE m197 ADD COLUMN c int;
ALTER TABLE m197 ENABLE ROW LEVEL SECURITY;
ALTER TABLE v197 RENAME COLUMN a TO z;
ALTER TABLE v197 RENAME TO w197;
ALTER TABLE t197 CLUSTER ON nosuch197;
ALTER TABLE t197 CLUSTER ON i197;
INSERT INTO w197 (b) VALUES (5) RETURNING *;
SELECT attname, pg_get_expr(adbin, adrelid) FROM pg_attrdef d
  JOIN pg_attribute a ON a.attrelid = d.adrelid AND a.attnum = d.adnum
  WHERE adrelid = 'w197'::regclass ORDER BY 1;
CREATE FOREIGN DATA WRAPPER w197;
CREATE SERVER s197 FOREIGN DATA WRAPPER w197;
CREATE FOREIGN TABLE f197(a int NOT NULL, b int) SERVER s197;
ALTER TABLE f197 OPTIONS (ADD x 'y');
ALTER TABLE f197 ALTER COLUMN a OPTIONS (ADD x 'y');
ALTER TABLE f197 SET UNLOGGED;
ALTER FOREIGN TABLE f197 ENABLE RULE r;
ALTER TABLE f197 ENABLE ROW LEVEL SECURITY;
ALTER TABLE f197 ALTER COLUMN b SET DEFAULT 4;
ALTER TABLE f197 ENABLE TRIGGER nosuch197;
ALTER TABLE f197 ALTER COLUMN a DROP EXPRESSION;
ALTER TABLE t197 OPTIONS (ADD x 'y');
ALTER TABLE t197 VALIDATE CONSTRAINT nosuch197;
SELECT ftoptions FROM pg_foreign_table WHERE ftrelid = 'f197'::regclass;
